use std::fs

struct Tree {
    keys: Vec<int>,
    lefts: Vec<int>,
    rights: Vec<int>,
    root: int,
}

impl Tree {
    fn height_of(self, n: int) -> int {
        if n < 0 {
            return 0
        }
        let a = self.height_of(self.lefts[n as usize])
        let b = self.height_of(self.rights[n as usize])
        if a > b { a + 1 } else { b + 1 }
    }

    fn contains(self, x: int) -> bool {
        let mut cur = self.root
        while cur >= 0 {
            let k = self.keys[cur as usize]
            if x == k {
                return true
            }
            if x < k {
                cur = self.lefts[cur as usize]
            } else {
                cur = self.rights[cur as usize]
            }
        }
        false
    }

    fn insert(self, x: int) -> bool {
        if self.contains(x) {
            return false
        }
        let idx = self.keys.len() as int
        self.keys.push(x)
        self.lefts.push(-1)
        self.rights.push(-1)
        if self.root < 0 {
            self.root = idx
            return true
        }
        let mut cur = self.root
        loop {
            let k = self.keys[cur as usize]
            if x < k {
                let l = self.lefts[cur as usize]
                if l < 0 {
                    self.lefts[cur as usize] = idx
                    return true
                }
                cur = l
            } else {
                let r = self.rights[cur as usize]
                if r < 0 {
                    self.rights[cur as usize] = idx
                    return true
                }
                cur = r
            }
        }
    }

    fn set_child(self, parent: int, was_left: bool, child: int) {
        if parent < 0 {
            self.root = child
        } else if was_left {
            self.lefts[parent as usize] = child
        } else {
            self.rights[parent as usize] = child
        }
    }

    fn delete(self, x: int) -> bool {
        let mut cur = self.root
        let mut parent = -1
        let mut was_left = false
        while cur >= 0 {
            let k = self.keys[cur as usize]
            if x == k {
                break
            }
            parent = cur
            if x < k {
                was_left = true
                cur = self.lefts[cur as usize]
            } else {
                was_left = false
                cur = self.rights[cur as usize]
            }
        }
        if cur < 0 {
            return false
        }
        let l = self.lefts[cur as usize]
        let r = self.rights[cur as usize]
        if l >= 0 && r >= 0 {
            let mut sp = cur
            let mut s = r
            let mut sleft = false
            while self.lefts[s as usize] >= 0 {
                sp = s
                sleft = true
                s = self.lefts[s as usize]
            }
            self.keys[cur as usize] = self.keys[s as usize]
            let sr = self.rights[s as usize]
            self.set_child(sp, sleft, sr)
        } else if l >= 0 {
            self.set_child(parent, was_left, l)
        } else {
            self.set_child(parent, was_left, r)
        }
        true
    }

    fn inorder(self) -> string {
        let mut out = ""
        let mut stack: Vec<int> = []
        let mut cur = self.root
        let mut first = true
        while cur >= 0 || stack.len() > 0 {
            while cur >= 0 {
                stack.push(cur)
                cur = self.lefts[cur as usize]
            }
            let n = stack.pop() ?? 0
            if first {
                out = "${self.keys[n as usize]}"
                first = false
            } else {
                out = "${out} ${self.keys[n as usize]}"
            }
            cur = self.rights[n as usize]
        }
        if first { "<empty>" } else { out }
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut t = Tree { keys: [], lefts: [], rights: [], root: -1 }
    for line in text.lines() {
        let mut parts: Vec<string> = []
        for p in line.split_whitespace() {
            parts.push(p.to_string())
        }
        if parts.len() == 0 {
            continue
        }
        let cmd = parts[0]
        if cmd == "insert" {
            let x: int = parts[1].parse() ?? 0
            if t.insert(x) { println("ok") } else { println("dup") }
        } else if cmd == "contains" {
            let x: int = parts[1].parse() ?? 0
            if t.contains(x) { println("yes") } else { println("no") }
        } else if cmd == "delete" {
            let x: int = parts[1].parse() ?? 0
            if t.delete(x) { println("ok") } else { println("missing") }
        } else if cmd == "inorder" {
            println(t.inorder())
        } else if cmd == "height" {
            println("${t.height_of(t.root)}")
        } else if cmd == "min" || cmd == "max" {
            if t.root < 0 {
                println("empty")
            } else {
                let mut c = t.root
                if cmd == "min" {
                    while t.lefts[c as usize] >= 0 { c = t.lefts[c as usize] }
                } else {
                    while t.rights[c as usize] >= 0 { c = t.rights[c as usize] }
                }
                println("${t.keys[c as usize]}")
            }
        }
    }
}

